    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn mismatched_quotes_are_kept_as_is() {
        let content = "KEY=\"value'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"value'".to_string()));
    }

    #[test]
    fn mismatched_quotes_single_then_double() {
        let content = "KEY='value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn empty_double_quotes() {
        let content = "KEY=\"\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn empty_single_quotes() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn single_double_quote_character_value() {
        // A lone `"` starts_with and ends_with `"`, but len is 1 (< 2)
        let content = "KEY=\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn single_single_quote_character_value() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn nested_single_quotes_inside_double_quotes() {
        let content = "KEY=\"it's a value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a value".to_string()));
    }

    #[test]
    fn nested_double_quotes_inside_single_quotes() {
        let content = r#"KEY='she said "hi"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"she said \"hi\"".to_string()));
    }

    #[test]
    fn quotes_in_middle_of_unquoted_value() {
        let content = "KEY=val\"ue";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"val\"ue".to_string()));
    }

    #[test]
    fn double_quoted_value_with_spaces() {
        let content = "KEY=\"  leading and trailing  \"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  leading and trailing  ".to_string())
        );
    }

    #[test]
    fn single_quoted_value_with_spaces() {
        let content = "KEY='  spaces  '";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  spaces  ".to_string()));
    }

    // --- Escaped characters ---

    #[test]
    fn backslash_n_in_double_quotes_is_literal() {
        // The parser does NOT interpret escape sequences
        let content = r#"KEY="hello\nworld""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"hello\nworld".to_string()));
    }

    #[test]
    fn backslash_t_in_double_quotes_is_literal() {
        let content = r#"KEY="col1\tcol2""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"col1\tcol2".to_string()));
    }

    #[test]
    fn escaped_double_quote_inside_double_quotes_is_literal() {
        // The parser strips outer quotes but does NOT process backslash escapes,
        // so `\"` remains as literal backslash + quote in the result.
        let content = r#"KEY="say \"hello\"""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say \"hello\""#.to_string()));
    }

    #[test]
    fn backslash_in_unquoted_value_is_literal() {
        let content = r"KEY=C:\Users\name";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"C:\Users\name".to_string()));
    }

    #[test]
    fn backslash_in_single_quoted_value_is_literal() {
        let content = r"KEY='C:\path\to\file'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"C:\path\to\file".to_string()));
    }

    #[test]
    fn double_backslash_in_quoted_value() {
        let content = r#"KEY="path\\to\\file""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"path\\to\\file".to_string()));
    }

    // --- Key edge cases ---

    #[test]
    fn equals_only_line_produces_empty_key_and_value() {
        let content = "=";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"".to_string()));
    }

    #[test]
    fn equals_with_value_but_no_key() {
        let content = "=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_dots() {
        let content = "app.setting.name=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("app.setting.name"), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_dashes() {
        let content = "MY-KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("MY-KEY"), Some(&"value".to_string()));
    }

    // --- Inline comments are NOT stripped ---

    #[test]
    fn inline_comment_is_included_in_value() {
        let content = "KEY=value # this is not stripped";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is not stripped".to_string())
        );
    }

    #[test]
    fn hash_in_quoted_value_is_preserved() {
        let content = "KEY=\"value # preserved\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value # preserved".to_string()));
    }

    // --- Export prefix ---

    #[test]
    fn export_prefix_becomes_part_of_key() {
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        // The parser doesn't strip "export ", it becomes part of the key
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    // --- Multiple equals signs ---

    #[test]
    fn multiple_equals_in_value() {
        let content = "KEY=a=b=c=d";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn base64_value_with_trailing_equals() {
        let content = "SECRET=dGVzdA==";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("SECRET"), Some(&"dGVzdA==".to_string()));
    }

    // --- Whitespace handling ---

